  status: 'starting' | 'running' | 'stopped' | 'failed';
  layer: string;
  created: Date;
  execute(): Promise<any>;
  stop(): Promise<void>;
}

export class UniversalRuntime {
  private platform: string;
  private bridge: PlatformBridge;
  private layerManager: LayerManager;

  constructor(config: RuntimeConfig = {}) {
    this.platform = config.platform || 'auto';
    if (this.platform === 'auto') {
      this.platform = this.detectPlatform();
    }
    this.bridge = new PlatformBridge(this.platform);
    this.layerManager = new LayerManager();
  }

  private detectPlatform(): string {
    // 檢測運行平台
    if (typeof process !== 'undefined') {
      if (process.versions?.node) {
        return 'node';
      }
    }
    if (typeof window !== 'undefined') {
      return 'browser';
    }
    return process.platform || 'linux';
  }

  async spawn(container: FlpkgContainer, config: RuntimeConfig = {}): Promise<RuntimeInstance> {
    const instance: RuntimeInstance = {
      id: this.generateId(),
      platform: this.platform,
      status: 'starting',
      layer: config.layer || 'L3',
      created: new Date(),
      execute: async () => {
        instance.status = 'running';
        return await this.executeContainer(container, config);
      },
      stop: async () => {
        instance.status = 'stopped';
      }
    };

    return instance;
  }

  private async executeContainer(container: FlpkgContainer, config: RuntimeConfig): Promise<any> {
    // 根據層級載入粒子
    const particles = await this.layerManager.loadParticles(config.layer || 'L3');

    // 執行容器
    return await this.bridge.execute(container, particles);
  }

  private generateId(): string {
    return `runtime-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}
