    'L3': { level: 'L3', name: 'LAW', nameCN: '法則層', purpose: 'Business logic' },
    'L4': { level: 'L4', name: 'WORLD', nameCN: '連接層', purpose: 'External connections' },
    'L5': { level: 'L5', name: 'MIRROR', nameCN: '鏡像層', purpose: 'Backup/redundancy' },
    'L6': { level: 'L6', name: 'REFLECT', nameCN: '投影層', purpose: 'UI/API projection' },
    'L7': { level: 'L7', name: 'LOOP', nameCN: '驗證層', purpose: 'Verification' },
