export class FlpkgPacker {
  async pack(content: any, outputPath: string, options: PackOptions = {}): Promise<string> {
    const manifest = {
      format: 'flpkg/1.0',
      version: '1.0.0',
      origin_signature: options.origin_signature || 'MrLiouWord',
      created: new Date().toISOString(),
      encrypted: options.encrypted || false,
      layer: options.layer,
      content
    };

    const json = JSON.stringify(manifest, null, 2);
    await fs.promises.writeFile(outputPath, json, 'utf-8');

    return outputPath;
  }
}
