    const env_id = req.env_id || this.generateEnvId();

    const env = {
      id: env_id,
      role: req.role || 'core',
      shape: req.shape,
      policy: req.policy || 'Mr.liou.MetaCode.Guard.v1',
      status: 'starting',
      created: new Date()
    };

    this.envs.set(env_id, env);

    // 啟動環境
    setTimeout(() => {
      env.status = 'running';
    }, 100);

    return {
      ok: true,
      env_id,
      status: 'starting'
    };
  }

  async health(env_id?: string): Promise<any> {
    if (env_id) {
      const env = this.envs.get(env_id);
      return {
        ok: env?.status === 'running',
        time: new Date().toISOString(),
        env_id,
        status: env?.status
      };
    }

    return {
      ok: true,
      time: new Date().toISOString(),
      total_envs: this.envs.size
    };
  }

  private generateEnvId(): string {
    return `env-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
