      actions.push('Disconnected all external connections');
      actions.push('Revoked all tokens');
      actions.push('Froze all snapshots');
    } else if (req.env_id) {
      // 單一環境鎖死
      this.locked.add(req.env_id);
      actions.push(`Locked environment: ${req.env_id}`);
    }

    return {
      ok: true,
      actions
    };
  }

  isLocked(env_id: string): boolean {
    return this.locked.has(env_id);
  }
}
