```python
"""
Trace Miner
追蹤挖掘器 - 從 trace 檔案產生規則和通道地圖

Origin Signature: MrLiouWord
"""

import pandas as pd
import json
from pathlib import Path
from typing import Dict, List, Any

class TraceMiner:
    def __init__(self):
        self.rules = []
        self.channel_map = {}

    def mine(self, trace_fs_path: str, trace_ops_path: str) -> Dict[str, Any]:
        """
        分析 trace 檔案並產生規則

        Args:
            trace_fs_path: trace_fs.csv 路徑
            trace_ops_path: trace_ops.csv 路徑

        Returns:
            包含 rules 和 channel_map 的字典
        """
        # 讀取 trace 檔案
        df_fs = pd.read_csv(trace_fs_path)
        df_ops = pd.read_csv(trace_ops_path)

        # 分析檔案操作模式
        patterns = self._analyze_patterns(df_fs, df_ops)

        # 產生規則
        self.rules = self._generate_rules(patterns)

        # 建立通道地圖
        self.channel_map = self._build_channel_map(patterns)

        return {
            'rules': self.rules,
            'channel_map': self.channel_map,
            'stats': {
                'total_operations': len(df_ops),
                'unique_paths': df_fs['fullpath'].nunique(),
                'patterns_found': len(patterns)
            }
        }

    def _analyze_patterns(self, df_fs: pd.DataFrame, df_ops: pd.DataFrame) -> List[Dict]:
        """分析檔案操作模式"""
        patterns = []

        # 分析常見路徑
        common_paths = df_fs['fullpath'].value_counts().head(10)
        for path, count in common_paths.items():
            patterns.append({
                'type': 'frequent_path',
                'path': path,
                'count': count
            })

        return patterns

    def _generate_rules(self, patterns: List[Dict]) -> List[Dict]:
        """產生規則"""
        rules = []

        for pattern in patterns:
            if pattern['type'] == 'frequent_path':
                rules.append({
                    'condition': f"path.contains('{Path(pattern['path']).parent}')",
                    'action': 'log',
                    'priority': pattern['count']
                })

        return rules

    def _build_channel_map(self, patterns: List[Dict]) -> Dict:
        """建立通道地圖"""
        channel_map = {}

        for pattern in patterns:
            if pattern['type'] == 'frequent_path':
                path = Path(pattern['path'])
                channel_map[str(path.parent)] = {
                    'source': 'FlowMemory:/detected',
                    'target': str(path.parent),
                    'frequency': pattern['count']
                }

        return channel_map

    def export_yaml(self, output_path: str):
        """匯出為 YAML 格式"""
        import yaml

        data = {
            'rules': self.rules,
            'channel_map': self.channel_map
        }

        with open(output_path, 'w', encoding='utf-8') as f:
            yaml.dump(data, f, allow_unicode=True)

if __name__ == '__main__':
    import sys

    if len(sys.argv) < 3:
        print('Usage: python TraceMiner.py <trace_fs.csv> <trace_ops.csv>')
        sys.exit(1)

    miner = TraceMiner()
    result = miner.mine(sys.argv[1], sys.argv[2])

    print('✅ Analysis Complete')
    print(f"Rules: {len(result['rules'])}")
    print(f"Channel Maps: {len(result['channel_map'])}")

    # 匯出結果
    miner.export_yaml('output_rules.yaml')
    print('📄 Exported to output_rules.yaml')
