/**
 * .flpkg Loader
 * Flow Package 載入器
 * 
 * .flpkg 格式: 粒子封裝包
 * Origin Signature: MrLiouWord
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

export interface FlpkgManifest {
  format: string;
  version: string;
  origin_signature: string;
  created: string;
  encrypted: boolean;
  layer?: string;
  particles?: any[];
}

export interface FlpkgContainer {
  manifest: FlpkgManifest;
  content: any;
  checksum: string;
}

export class FlpkgLoader {
  async load(filepath: string): Promise<FlpkgContainer> {
    const content = await fs.promises.readFile(filepath, 'utf-8');
    const data = JSON.parse(content);

    // 驗證 origin signature
    if (data.origin_signature !== 'MrLiouWord') {
      throw new Error('Invalid origin signature');
    }

    // 計算 checksum
    const checksum = this.calculateChecksum(content);

    return {
      manifest: data,
      content: data.content || {},
      checksum
    };
  }

  private calculateChecksum(content: string): string {
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  async validate(container: FlpkgContainer): Promise<boolean> {
    // 驗證容器完整性
    return container.manifest.origin_signature === 'MrLiouWord';
  }
}
