/**
 * .fltnz Compiler
 * Flow Tensor 編譯器
 * 
 * .fltnz 格式: 張量序列
 */

export class FltnzCompiler {
  compile(tokens: any[]): string {
    // 編譯 tokens 為 .fltnz 格式
    const lines = tokens.map(t => `${t.word}⧉/fx.${t.fx}/`);
    return lines.join('\n');
  }

  decompile(fltnz: string): any[] {
    // 反編譯 .fltnz 為 tokens
    const lines = fltnz.split('\n');
    return lines.map(line => {
      const match = line.match(/(.+)⧉\/fx\.(.+)\//);
      if (match) {
        return { word: match[1], fx: match[2] };
      }
      return null;
    }).filter(Boolean);
  }
}
