## 🎯 核心律法實現

### 1️⃣ **相機投影律法** (Camera Projection Law)

```typescript
/**
 * 相機投影律法
 * 基於 文字.txt 中的公式
 * Origin Signature: MrLiouWord
 */
export class CameraProjectionLaw implements Law {
  name = "Camera Projection Law";
  layer = "L3";

  // 1. 座標轉換（世界→相機）
  worldToCamera(Xw: Vector3, R: Matrix3x3, t: Vector3): Vector3 {
    // X_c = R * X_w + t
    return R.multiply(Xw).add(t);
  }

  // 2. 針孔投影（未畸變）
  pinholeProjection(Xc: Vector3, fx: number, fy: number, cx: number, cy: number): Vector2 {
    const x = Xc.x / Xc.z;
    const y = Xc.y / Xc.z;

    return {
      u: fx * x + cx,
      v: fy * y + cy
    };
  }

  // 3. OPENCV 畸變模型
  opencvDistortion(
    x: number, 
    y: number, 
    k1: number, k2: number, k3: number,
    p1: number, p2: number
  ): { x_distorted: number; y_distorted: number } {
    const r2 = x * x + y * y;
    const radial = 1 + k1 * r2 + k2 * r2 * r2 + k3 * r2 * r2 * r2;

    const x_distorted = x * radial + 2 * p1 * x * y + p2 * (r2 + 2 * x * x);
    const y_distorted = y * radial + p1 * (r2 + 2 * y * y) + 2 * p2 * x * y;

    return { x_distorted, y_distorted };
  }

  // 4. 四元數→旋轉矩陣
  quaternionToRotation(qw: number, qx: number, qy: number, qz: number): Matrix3x3 {
    const s = 1 / (qw*qw + qx*qx + qy*qy + qz*qz);

    return new Matrix3x3([
      [1 - 2*s*(qy*qy + qz*qz), 2*s*(qx*qy - qz*qw),     2*s*(qx*qz + qy*qw)],
      [2*s*(qx*qy + qz*qw),     1 - 2*s*(qx*qx + qz*qz), 2*s*(qy*qz - qx*qw)],
      [2*s*(qx*qz - qy*qw),     2*s*(qy*qz + qx*qw),     1 - 2*s*(qx*qx + qy*qy)]
    ]);
  }

  // 5. 重投影誤差
  reprojectionError(observed: Vector2, predicted: Vector2): number {
    const dx = observed.u - predicted.u;
    const dy = observed.v - predicted.v;
    return Math.sqrt(dx * dx + dy * dy);
  }

  // 6. Huber 損失
  huberLoss(error: number, delta: number): number {
    if (Math.abs(error) <= delta) {
      return 0.5 * error * error;
    } else {
      return delta * (Math.abs(error) - 0.5 * delta);
    }
  }
}
```

### 2️⃣ **注意力聚合律法** (Attention Aggregation Law)

```typescript
/**
 * 注意力聚合律法
 * 基於 文字.txt 中的公式
 */
export class AttentionAggregationLaw implements Law {
  name = "Attention Aggregation Law";
  layer = "L3";

  // 7. 注意力權重（Simple - 中心性）
  simpleAttention(u: number, v: number, cx: number, cy: number, W: number, H: number): number {
    const dx = (u - cx) / (W / 2);
    const dy = (v - cy) / (H / 2);
    const dist = Math.sqrt(dx * dx + dy * dy);
    return Math.max(0, 1 - dist);
  }

  // 8. 注意力加權誤差
  weightedError(error: number, attention: number): number {
    return attention * error;
  }

  // 9. 影像域熱圖聚合（像素級）
  heatmapAggregation(errors: number[], mode: 'max' | 'mean' | 'p90' = 'max'): number {
    if (errors.length === 0) return 0;

    switch (mode) {
      case 'max':
        return Math.max(...errors);
      case 'mean':
        return errors.reduce((a, b) => a + b, 0) / errors.length;
      case 'p90':
        const sorted = errors.slice().sort((a, b) => a - b);
        const idx = Math.floor(sorted.length * 0.9);
        return sorted[idx];
    }
  }

  // 10. 全圖統計指標
  imageStats(heatmap: number[][]): {
    p50: number;
    p90: number;
    coverage: number;
  } {
    const flat = heatmap.flat();
    const sorted = flat.slice().sort((a, b) => a - b);

    const p50 = sorted[Math.floor(sorted.length * 0.5)];
    const p90 = sorted[Math.floor(sorted.length * 0.9)];
    const coverage = flat.filter(v => v > 0).length / flat.length;

    return { p50, p90, coverage };
  }
}
```

### 3️⃣ **Mesh 覆蓋律法** (Mesh Coverage Law)

```typescript
/**
 * Mesh 覆蓋律法
 * 基於 文字.txt 中的公式
 */
export class MeshCoverageLaw implements Law {
  name = "Mesh Coverage Law";
  layer = "L3";

  // 11. 合成環繞相機
  synthesizeCameras(bbox: BoundingBox, N: number, alpha: number = 2.0): Camera[] {
    const center = bbox.center();
    const R = alpha * bbox.radius() / 2;

    const cameras: Camera[] = [];
    for (let k = 0; k < N; k++) {
      const theta = (2 * Math.PI * k) / N;
      const position = {
        x: center.x + R * Math.cos(theta),
        y: center.y,
        z: center.z + R * Math.sin(theta)
      };

      // 計算旋轉矩陣
      const z = normalize(subtract(center, position));
      const x = normalize(cross({ x: 0, y: 1, z: 0 }, z));
      const y = cross(z, x);

      const R_matrix = new Matrix3x3([
        [x.x, x.y, x.z],
        [y.x, y.y, y.z],
        [z.x, z.y, z.z]
      ]);

      const t = R_matrix.multiply(negate(position));

      cameras.push({ position, R: R_matrix, t });
    }

    return cameras;
  }

  // 12. Mesh/點雲投影
  projectMesh(vertices: Vector3[], camera: Camera, fx: number, fy: number, cx: number, cy: number): Vector2[] {
    return vertices.map(v => {
      const Xc = camera.R.multiply(v).add(camera.t);
      if (Xc.z <= 0) return null; // 背後的點

      return {
        u: fx * (Xc.x / Xc.z) + cx,
        v: fy * (Xc.y / Xc.z) + cy
      };
    }).filter(p => p !== null);
  }

  // 13. 覆蓋熱圖
  coverageHeatmap(projections: Vector2[][], W: number, H: number): number[][] {
    const heatmap = Array(H).fill(0).map(() => Array(W).fill(0));

    projections.forEach(points => {
      points.forEach(p => {
        const u = Math.floor(p.u);
        const v = Math.floor(p.v);
        if (u >= 0 && u < W && v >= 0 && v < H) {
          heatmap[v][u]++;
        }
      });
    });

    return heatmap;
  }
}
```

### 4️⃣ **資料格式律法** (Data Format Law)

```typescript
/**
 * 資料格式律法
 * 基於提供的 JSON/CSV 格式
 */
export class DataFormatLaw implements Law {
  name = "Data Format Law";
  layer = "L3";

  // 驗證 .flpkg.json 格式
  validateFlpkg(data: any): ValidationResult {
    const required = ['name', 'creator', 'fx_path', 'tokens', 'role', 'timestamp'];
    const missing = required.filter(key => !(key in data));

    if (missing.length > 0) {
      return {
        valid: false,
        violations: [`Missing required fields: ${missing.join(', ')}`]
      };
    }

    // 驗證 tokens 結構
    if (!Array.isArray(data.tokens)) {
      return { valid: false, violations: ['tokens must be an array'] };
    }

    for (const token of data.tokens) {
      if (!token.word || !token.fx) {
        return { valid: false, violations: ['Each token must have word and fx'] };
      }
    }

    return { valid: true };
  }

  // 驗證國家資料格式
  validateCountries(data: any): ValidationResult {
    if (!data.countries || !Array.isArray(data.countries)) {
      return { valid: false, violations: ['Must have countries array'] };
    }

    for (const country of data.countries) {
      if (!country.name || !country.isoCode) {
        return { valid: false, violations: ['Each country must have name and isoCode'] };
      }
      if (country.isoCode.length !== 2) {
        return { valid: false, violations: [`Invalid ISO code: ${country.isoCode}`] };
      }
    }

    return { valid: true };
  }

  // 驗證 Particle JSON
  validateParticleJSON(data: any): ValidationResult {
    const required = ['id', 'version', 'origin', 'stamp', 'particle'];
    const missing = required.filter(key => !(key in data));

    if (missing.length > 0) {
      return { valid: false, violations: [`Missing: ${missing.join(', ')}`] };
    }

    // 驗證 Origin Signature
    if (data.origin && !data.origin.pkg && !data.origin.node) {
      return { valid: false, violations: ['origin must have pkg or node'] };
    }

    return { valid: true };
  }
}
```

