    const patterns: Map<string, Pattern> = new Map();

    data.forEach((item, index) => {
      const fingerprint = this.generateFingerprint(item);

      if (!patterns.has(fingerprint)) {
        patterns.set(fingerprint, {
          fingerprint,
          count: 0,
          indices: [],
          sample: item
        });
      }

      const pattern = patterns.get(fingerprint)!;
      pattern.count++;
      pattern.indices.push(index);
    });

    return Array.from(patterns.values())
      .filter(p => p.count > 1) // 只返回重複的
      .sort((a, b) => b.count - a.count); // 按頻率排序
  }

