export class SimilarityMatcher {
  /**
   * 計算 Hamming Distance (用於 SimHash)
   */
  hammingDistance(hash1: string, hash2: string): number {
    let distance = 0;
    for (let i = 0; i < Math.min(hash1.length, hash2.length); i++) {
      if (hash1[i] !== hash2[i]) distance++;
    }
    return distance;
  }

  /**
   * 計算相似度 (0-1)
   */
  similarity(data1: any, data2: any): number {
    const hash1 = simhash64(JSON.stringify(data1));
    const hash2 = simhash64(JSON.stringify(data2));

    const distance = this.hammingDistance(hash1, hash2);
    const maxDistance = hash1.length * 4; // 64-bit = 16 hex chars

    return 1 - (distance / maxDistance);
  }

  /**
   * 找出最相似的項目
   */
  findMostSimilar(target: any, candidates: any[]): {
    item: any;
    similarity: number;
  } {
    let best = { item: null, similarity: 0 };

    candidates.forEach(candidate => {
      const sim = this.similarity(target, candidate);
      if (sim > best.similarity) {
        best = { item: candidate, similarity: sim };
      }
    });

    return best;
  }
}
