export class SimHashDeduper {
  /**
   * 去除完全重複
   */
  deduplicateExact(items: any[]): {
    unique: any[];
    duplicates: Map<string, any[]>;
  } {
    const seen = new Map<string, any>();
    const duplicates = new Map<string, any[]>();

    items.forEach(item => {
      const hash = simhash64(JSON.stringify(item));

      if (seen.has(hash)) {
        if (!duplicates.has(hash)) {
          duplicates.set(hash, [seen.get(hash)]);
        }
        duplicates.get(hash)!.push(item);
      } else {
        seen.set(hash, item);
      }
    });

    return {
      unique: Array.from(seen.values()),
      duplicates
    };
  }

  /**
   * 去除近似重複 (threshold = 0.95 表示 95% 相似即視為重複)
   */
  deduplicateSimilar(items: any[], threshold: number = 0.95): {
    unique: any[];
    clusters: Map<number, any[]>;
  } {
    const clusters = new Map<number, any[]>();
    let clusterId = 0;

    items.forEach(item => {
      const hash = simhash64(JSON.stringify(item));
      let foundCluster = false;

      // 檢查是否與現有 cluster 相似
      for (const [id, clusterItems] of clusters.entries()) {
        const representative = clusterItems[0];
        const repHash = simhash64(JSON.stringify(representative));

        const similarity = 1 - this.hammingDistance(hash, repHash) / 64;

        if (similarity >= threshold) {
          clusterItems.push(item);
          foundCluster = true;
          break;
        }
      }

      if (!foundCluster) {
        clusters.set(clusterId++, [item]);
      }
    });

    // 每個 cluster 取第一個作為代表
    const unique = Array.from(clusters.values()).map(cluster => cluster[0]);

    return { unique, clusters };
  }

  private hammingDistance(hash1: string, hash2: string): number {
    let distance = 0;
    for (let i = 0; i < Math.min(hash1.length, hash2.length); i++) {
      if (hash1[i] !== hash2[i]) distance++;
    }
    return distance;
  }
}
