/**
 * 比對器 - 找出差異和相似性
 */
export class Comparator {
  // SimHash 比對（Hamming 距離）
  compareSimHash(hash1: bigint, hash2: bigint): number {
    let xor = hash1 ^ hash2;
    let distance = 0;
    while (xor > 0n) {
      distance += Number(xor & 1n);
      xor >>= 1n;
    }
    return distance;
  }

  // 粒子相似度
  compareSimilarity(p1: Particle, p2: Particle): number {
    const hashDist = this.compareSimHash(p1.simhash, p2.simhash);
    const maxDist = 64; // 64-bit SimHash
    return 1 - (hashDist / maxDist);
  }

  // 狀態差異
  compareStates(state1: State, state2: State): Delta {
    return {
      added: this.findAdded(state1, state2),
      removed: this.findRemoved(state1, state2),
      modified: this.findModified(state1, state2)
    };
  }
}
