/**
 * 去重器 - 消除冗餘
 */
export class Deduplicator {
  // SimHash 去重
  deduplicateBySimHash(particles: Particle[], threshold: number = 5): Particle[] {
    const unique: Particle[] = [];
    const seen = new Set<string>();

    for (const p of particles) {
      const hash = p.simhash.toString();

      // 檢查是否已存在相似項
      let isDuplicate = false;
      for (const u of unique) {
        const distance = this.hammingDistance(p.simhash, u.simhash);
        if (distance <= threshold) {
          isDuplicate = true;
          break;
        }
      }

      if (!isDuplicate) {
        unique.push(p);
        seen.add(hash);
      }
    }

    return unique;
  }

  // δP₀ 壓縮去重
  compressDelta(deltas: DeltaUnit[]): CompressedDelta {
    // 合併連續的相同操作
    const compressed: DeltaUnit[] = [];
    let current: DeltaUnit | null = null;

    for (const delta of deltas) {
      if (current && this.canMerge(current, delta)) {
        current = this.merge(current, delta);
      } else {
        if (current) compressed.push(current);
        current = delta;
      }
    }

    if (current) compressed.push(current);

    return {
      original_count: deltas.length,
      compressed_count: compressed.length,
      compression_ratio: compressed.length / deltas.length,
      deltas: compressed
    };
  }
}
