### **Liou 閉合律法** (觀察+比對+去重)
```typescript
/**
 * Liou 閉合律法 = 觀察 + 比對 + 去重
 */
export class LiouClosureLaw implements Law {
  name = "Liou Closure Law (Observe + Compare + Deduplicate)";

  async optimize(data: any): Promise<OptimizationResult> {
    // 1. 觀察
    const observation = this.observer.observeParticles(data.particles);

    // 2. 比對
    const duplicates = [];
    for (let i = 0; i < observation.simhashes.length; i++) {
      for (let j = i + 1; j < observation.simhashes.length; j++) {
        const similarity = this.comparator.compareSimHash(
          observation.simhashes[i],
          observation.simhashes[j]
        );
        if (similarity < 5) { // Hamming distance < 5
          duplicates.push([i, j]);
        }
      }
    }

    // 3. 去重
    const unique = this.deduplicator.deduplicateBySimHash(data.particles);

    return {
      original_count: data.particles.length,
      unique_count: unique.length,
      duplicates_found: duplicates.length,
      compression_ratio: unique.length / data.particles.length,
      particles: unique
    };
  }
}
