export class ReversibilityLaw implements Law {
  name = "Reversibility Law (Decompose + Compose)";

  async optimize(operation: Operation): Promise<ReversibleOperation> {
    // 1. 拆解為 δP₀
    const deltas = this.decomposer.decomposeToDelta(operation.state);

    // 2. 確保每個 δ 都可逆
    const reversibleDeltas = deltas.map(delta => ({
      ...delta,
      inverse: this.computeInverse(delta)
    }));

    // 3. 組合成可逆操作
    const reversible = {
      forward: operation,
      backward: this.composer.recomposeFromDelta(
        operation.state,
        reversibleDeltas.map(d => d.inverse)
      ),
      deltas: reversibleDeltas
    };

    return reversible;
  }
}
